import * as C from './core.js';
import {socialConfig,currentId,membership,profileOf,accountOf} from './social-core.js';
import {GUILD_ROLES,eventState} from './guilds.js';
export function createSocialView(env){const {escape:esc,icon:I,coin,sprite,button:btn,heading,assetUrl,input,textarea,modal,format:n}=env;let room='global';
 const note=()=>env.isDemo?'<div class="notice">Demonstração local: mensagens, negociações e guerras não conectam outros jogadores nesta versão. Os perfis de exemplo estão identificados.</div>':'';
 const picture=(state,id)=>{const known=id===currentId(state)||state.adminAccounts?.some(a=>a.profile.id===id),model=env.isDemo&&known?state.catalog.find(r=>r.id===accountOf(state,id).robots[0]?.catalogId):null;return sprite(model||state.catalog[0]);};
 const guildById=id=>env.getState().social?.guilds.find(g=>g.id===id);
 const receivedInvite=()=>{const state=env.getState(),params=new URL(env.baseUrl()).searchParams,guild=state.social?.guilds.find(g=>g.inviteCode===params.get('guild'));if(!guild)return null;const code=String(params.get('invite')||'').toUpperCase(),profile=env.isDemo?[state.profile,...state.adminAccounts.map(a=>a.profile)].find(p=>p.referralCode===code):null;return {guild,code,inviterId:profile&&guild.members.some(m=>m.userId===profile.id)?profile.id:null};};
 const inviteLink=()=>{const s=env.getState(),own=membership(s);if(!own)return '';const url=new URL(env.baseUrl());url.search='';url.hash='guilds';url.searchParams.set('guild',own.guild.inviteCode);url.searchParams.set('invite',s.profile.referralCode);return url.href;};
 const getChannel=()=>{const own=membership(env.getState());return room==='guild'?(own?'guild:'+own.guild.id:null):room;};
 const roomTitle=()=>room==='global'?'Praça de Aurora':room==='market'?'Negociações de robôs':membership(env.getState())?.guild.name||'Entre em uma guilda';
 function chatPanel({floating=false,draft=''}={}){const s=env.getState(),cfg=socialConfig(s),own=membership(s),channel=getChannel(),messages=(s.social?.messages||[]).filter(m=>m.room===channel).slice(0,cfg.chatHistoryLimit).reverse();
  return `<section class="game-chat"><div class="chat-room-tabs">${[['global','Global','users'],['market','Mercado','shop'],['guild','Guilda','shield']].map(([id,label,icon])=>`<button data-a="chat-room" data-id="${id}" class="${room===id?'active':''}">${I(icon)} ${label}</button>`).join('')}</div><div class="chat-room-heading"><b>${room==='global'?'Praça de Aurora':room==='market'?'Negociações de robôs':own?.guild.name||'Entre em uma guilda'}</b><small>${env.isDemo?'Canal demonstrativo':'Canal da comunidade'}</small></div><div class="chat-messages" role="log" aria-label="Mensagens do canal" aria-live="polite">${messages.map(m=>`<article class="chat-message ${m.authorId===currentId(s)?'mine':''}"><span class="chat-avatar">${picture(s,m.authorId)}</span><div><header><b>${esc(m.name)}</b><small>${m.example?'EXEMPLO · ':''}${new Date(m.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></header><p>${esc(m.text)}</p></div></article>`).join('')||'<div class="chat-empty"><span>'+I('users')+'</span><p>O canal está pronto para o primeiro sinal.</p></div>'}</div>${room==='guild'&&!own?`<div class="chat-join-guild">${btn('Encontrar guilda','goto','data-page="guilds"','primary wide')}</div>`:`<form id="${floating?'floating-chat-form':'chat-form'}" class="chat-composer" data-room="${esc(channel)}"><textarea name="message" aria-label="Sua mensagem" placeholder="Envie seu sinal…" maxlength="${cfg.chatMaxLength}" rows="2" required>${esc(draft)}</textarea><button type="submit" class="btn primary" ${!cfg.chatEnabled?'disabled':''}>${I('arrow')} Enviar</button><small>Até ${cfg.chatMaxLength} caracteres · Intervalo ${cfg.chatCooldownSeconds}s</small></form>`}</section>`;
 }
 function chat(){return `${heading('CENTRAL DE COMUNICAÇÃO','O próximo sinal vem da equipe.','Converse, organize sua guilda e encontre parceiros no mercado.')}${note()}${chatPanel()}<div class="social-quick-links">${btn('Guildas','goto','data-page="guilds"','secondary')}${btn('Mercado de robôs','goto','data-page="market"','secondary')}</div>`;}
 function eventCards(s){return `<div class="guild-event-grid">${(s.social?.events||[]).map(def=>{const event=eventState(s,def.id),board=s.social.warScores[def.id]||{},own=membership(s),rank=Object.entries(board).sort((a,b)=>b[1].points-a[1].points);return `<article class="guild-event-card"><div class="guild-event-art" style="background-image:url('${assetUrl(event.scene+'.png')}')"><span class="event-phase ${event.phase}">${{active:'EM DISPUTA',upcoming:'EM BREVE',ended:'ENCERRADO',paused:'PAUSADO'}[event.phase]}</span><img src="${assetUrl('guild-crest.png')}" alt="Guerra de guildas"></div><div><span class="eyebrow">GUERRA DE GUILDAS</span><h2>${esc(event.name)}</h2><p>${esc(event.description)}</p><div class="event-period"><span>${I('clock')} ${new Date(event.startsAt).toLocaleDateString('pt-BR')} → ${new Date(event.endsAt).toLocaleDateString('pt-BR')}</span><b>${Math.max(0,Math.ceil((event.endsAt-Date.now())/C.DAY))} dias restantes</b></div><div class="event-rewards"><span>${coin('RC')}<b>${n(event.battleRewardRC)} RC</b><small>Vitória individual</small></span><span>${coin('RC')}<b>${n(event.rewardPoolRC)} RC</b><small>Pool da guilda vencedora</small></span><span>${coin('RC')}<b>${n(event.participationRC)} RC</b><small>Participação no fim</small></span></div><div class="guild-scoreboard">${rank.length?rank.map(([id,data],i)=>`<div><b>${i+1}</b><span>${esc(guildById(id)?.name||'Guilda')}</span><strong>${data.points} pontos</strong></div>`).join(''):'<small>Nenhum duelo registrado nesta edição.</small>'}</div>${event.phase==='active'?btn(I('arena')+' Entrar na fortaleza','guild-war-start',`data-id="${event.id}" ${!own?'disabled':''}`,'primary wide'):event.phase==='ended'?btn('Resgatar prêmio do evento','guild-war-claim',`data-id="${event.id}"`,'primary wide'):btn('Acompanhar o evento','guild-event-info',`data-id="${event.id}"`,'secondary wide')}<small class="event-reward-note">Pool dividido entre participantes elegíveis da equipe vencedora.${env.isDemo?' Valores de teste.':''}</small></div></article>`;}).join('')}</div>`;}
 function guilds(){const s=env.getState(),cfg=socialConfig(s),own=membership(s),incoming=receivedInvite();return `${heading('GUILDAS','Uma equipe. Um só farol.','Crie sua guilda, forme a hierarquia e dispute territórios.',!own?btn(I('plus')+' Criar guilda · '+cfg.guildCreateCost+' RC','guild-create'):'')}${note()}${incoming&&!own?`<section class="guild-incoming-invite"><img src="${assetUrl('guild-crest.png')}" alt="Convite de guilda"><div><span class="eyebrow">UM CONVITE CHEGOU</span><h2>${esc(incoming.guild.name)}</h2><p>Código ${esc(incoming.guild.inviteCode)} · Conheça a equipe antes de entrar.</p></div>${btn('Ver convite','guild-roster',`data-id="${incoming.guild.id}"`,'primary')}</section>`:''}${own?`<section class="guild-home" style="--guild-art:url('${assetUrl('guild-canyon.png')}')"><div class="guild-home-identity"><img src="${assetUrl('guild-crest.png')}" alt="Brasão da guilda"><span class="eyebrow">[${esc(own.guild.tag)}] · ${GUILD_ROLES[own.member.role]}</span><h1>${esc(own.guild.name)}</h1><p>${esc(own.guild.description)}</p></div><div class="guild-level"><b>NV. ${own.guild.level}</b><span>${own.guild.xp} XP</span><div><i style="width:${Math.min(100,own.guild.xp%cfg.guildXPPerLevel/cfg.guildXPPerLevel*100)}%"></i></div><small>${own.guild.members.length}/${cfg.guildCapacity} membros · ${cfg.guildXPPerLevel} XP por nível</small></div><div class="guild-home-actions">${btn(I('copy')+' Compartilhar convite','guild-invite','','primary')}${btn(I('users')+' Chat da guilda','guild-chat','','secondary')}${s.social.activeGuildBattle?btn('Retomar duelo','guild-war-resume','','secondary'):''}${btn('Membros e hierarquia','guild-roster',`data-id="${own.guild.id}"`,'secondary')}</div></section><div class="guild-invite-bonuses">${[1,2,3].map(level=>`<article><span>NÍVEL ${level} DE CONVITE</span><b>${coin('RC')}${cfg['guildInviteLevel'+level]} RC</b><small>${level===1?'Convidados diretos':'Convidados da sua rede na guilda'} · crédito único por entrada elegível</small></article>`).join('')}</div><div class="guild-milestones">${Object.entries(own.guild.milestones).map(([level,m])=>{const key=`guild-level:${own.guild.id}:${level}:${currentId(s)}`,claimed=s.social.rewardReceipts.some(r=>r.key===key);return `<article><img src="${assetUrl('reward-chest.png')}" alt="Recompensa de nível"><div><b>Marco do nível ${level}</b><small>${m.rewardRC} RC por membro participante</small></div>${btn(claimed?'Resgatado':'Resgatar','guild-level-claim',`data-id="${level}" ${claimed||!m.eligibleIds.includes(currentId(s))?'disabled':''}`,'secondary')}</article>`;}).join('')}</div>`:`<section class="guild-discovery-hero"><img src="${assetUrl('guild-crest.png')}" alt="Brasão"><div><h2>Seu próximo capítulo é em equipe.</h2><p>Líderes organizam a guilda, oficiais ajudam a cuidar dos membros e cada piloto contribui nos duelos. Convites elegíveis dão bônus em até três níveis.</p></div></section>`}<div class="section-title"><h2>Eventos e guerras</h2><span>${cfg.guildDailyBattles} duelos por piloto / dia</span></div>${own?env.robotSelector():''}${eventCards(s)}<div class="section-title"><h2>Guildas de Aurora</h2></div><div class="guild-discovery-list">${(s.social?.guilds||[]).map(g=>`<article><img src="${assetUrl('guild-crest.png')}" alt="Brasão"><div><span class="eyebrow">[${esc(g.tag)}] ${g.example?'· EXEMPLO':''}</span><h3>${esc(g.name)}</h3><p>NV. ${g.level} · ${g.members.length}/${cfg.guildCapacity} membros</p><small>${esc(g.description)}</small></div>${btn(own?.guild.id===g.id?'Minha equipe':own?'Ver guilda':'Entrar / conhecer','guild-roster',`data-id="${g.id}"`,'secondary')}</article>`).join('')}</div>`;}
 function market(){const s=env.getState(),ownId=currentId(s),listings=(s.social?.listings||[]).filter(l=>['open','proposal'].includes(l.status)),cfg=socialConfig(s);return `${heading('MERCADO','Cada robô tem uma próxima história.','Negocie LC ou proponha uma troca com outro piloto.',btn(I('plus')+' Anunciar robô','trade-create'))}${note()}<section class="market-banner"><img src="${assetUrl('trade-terminal.png')}" alt="Terminal de trocas"><div><h2>Uma transferência. Um novo companheiro.</h2><p>O robô preserva nível, prazo, usos e o direito de devolução. Equipamentos ficam com o vendedor. Trocas precisam da aceitação dos dois participantes.</p><div><span>Venda: ${cfg.tradeFeePercent}% de taxa LC</span><span>Troca: ${cfg.tradeSwapFeeRC} RC por participante</span><span>Ofertas: ${cfg.tradeExpireDays} dias</span></div></div></section><div class="market-listings">${listings.map(l=>{let info;if(env.isDemo){const a=accountOf(s,l.sellerId),r=a.robots.find(r=>r.uid===l.robotUid);if(r)info=C.robotInfo(a,{...r,equipment:[]});}else info=l.robotSnapshot;if(!info)return '';return `<article class="market-robot-card" style="--robot-color:${info.color}"><div class="market-robot-art">${sprite(info)}<span class="rarity">${esc(info.rarity)}</span><b>NV. ${info.level}</b></div><div><span class="eyebrow">${l.kind==='sale'?'OFERTA EM LC':'TROCA ENTRE PILOTOS'} ${l.example?'· EXEMPLO':''}</span><h2>${esc(info.name)}</h2><p>${esc(profileOf(s,l.sellerId)?.name||l.sellerName||'Piloto')}</p><div class="market-robot-meta"><span>${info.daily} RC/dia</span><span>${Math.max(0,Math.ceil((info.expires-Date.now())/C.DAY))} dias restantes</span><span>${info.remainingBattles} usos restantes</span><span>${info.principalReturnLC} LC de devolução</span></div><div class="market-offer-action"><b>${l.kind==='sale'?coin('LC')+' '+n(l.priceLC)+' LC':'Proponha seu robô'}</b>${l.sellerId===ownId?btn('Cancelar','trade-cancel',`data-id="${l.id}" ${l.status!=='open'?'disabled':''}`,'secondary'):btn(l.status==='proposal'?'Em negociação':l.kind==='sale'?'Ver aquisição':'Propor troca','trade-open',`data-id="${l.id}" ${l.status!=='open'||!info.active?'disabled':''}`,'primary')}</div></div></article>`;}).join('')||'<div class="empty">Nenhuma oferta disponível.</div>'}</div><div class="section-title"><h2>Propostas e histórico</h2></div><div class="trade-proposals">${(s.social?.proposals||[]).filter(p=>p.buyerId===ownId||p.sellerId===ownId).map(p=>`<article><span>${I('shop')} Proposta de troca</span><b>${esc(profileOf(s,p.buyerId)?.name||'Piloto')} → ${esc(profileOf(s,p.sellerId)?.name||'Piloto')}</b><small>${{pending:'Aguardando contraparte',accepted:'Troca concluída',declined:'Proposta recusada',expired:'Proposta expirada'}[p.status]||p.status}</small>${p.status==='pending'?`${p.sellerId===ownId?btn('Aceitar troca','trade-review',`data-id="${p.id}" data-accept="true"`,'primary'):env.isDemo?btn('Testar aceite da contraparte (exemplo)','trade-demo-accept',`data-id="${p.id}"`,'secondary'):''}${btn('Recusar / cancelar','trade-review',`data-id="${p.id}" data-accept="false"`,'text')}`:''}</article>`).join('')||'<p class="subtle">Suas propostas aparecerão aqui.</p>'}</div><div class="trade-history">${(s.social?.trades||[]).filter(t=>t.buyerId===ownId||t.sellerId===ownId).map(t=>`<article>${I('check')}<span>${t.otherUid?'Troca concluída':'Transferência concluída'} · ${new Date(t.at).toLocaleDateString('pt-BR')}</span><b>${t.priceLC?n(t.priceLC)+' LC':'Robô ↔ Robô'}</b></article>`).join('')}</div>${btn('Conversar no canal Mercado','market-chat','','secondary wide')}`;}
 function createGuildForm(){const s=env.getState();modal(`<img class="social-modal-art" src="${assetUrl('guild-crest.png')}" alt="Brasão"><h2 id="modal-title">Acenda o farol da sua guilda.</h2><form id="guild-create-form">${input('Nome da guilda','name','','text','minlength="3" maxlength="35" required')}${input('Sigla','tag','','text','minlength="2" maxlength="5" required')}${textarea('A história da equipe','description','')}<p>Criação: ${socialConfig(s).guildCreateCost} RC · Você assume a liderança.</p><button class="btn primary wide" type="submit">Criar guilda</button></form>`);}
 function roster(id){const s=env.getState(),g=guildById(id),own=membership(s);if(!g)return;const incoming=receivedInvite(),inviter=incoming?.guild.id===id?incoming.inviterId:null,inviteCode=incoming?.guild.id===id?incoming.code:'';
  modal(`<div class="guild-roster-heading"><img src="${assetUrl('guild-crest.png')}" alt="Brasão"><div><span class="eyebrow">[${esc(g.tag)}] · NV. ${g.level}</span><h2 id="modal-title">${esc(g.name)}</h2><p>${esc(g.description)}</p></div></div><div class="guild-roster-list">${g.members.map(member=>`<article><span class="guild-member-avatar">${picture(s,member.userId)}</span><div><b>${esc(profileOf(s,member.userId)?.name||'Piloto')}</b><span>${GUILD_ROLES[member.role]}</span><small>Convites diretos: ${g.members.filter(m=>m.invitedBy===member.userId).length}</small></div>${own?.guild.id===id&&own.member.role==='officer'&&member.role==='member'?btn('Remover membro','guild-member-action',`data-guild="${id}" data-id="${member.userId}" data-action="kick"`,'text'):''}${own?.guild.id===id&&own.member.role==='leader'&&member.userId!==currentId(s)?`<div class="guild-role-actions">${btn(member.role==='officer'?'Tornar membro':'Promover oficial','guild-member-action',`data-guild="${id}" data-id="${member.userId}" data-action="${member.role==='officer'?'member':'officer'}"`,'secondary')}${btn('Transferir liderança','guild-member-action',`data-guild="${id}" data-id="${member.userId}" data-action="leader"`,'text')}${btn('Remover','guild-member-action',`data-guild="${id}" data-id="${member.userId}" data-action="kick"`,'text')}</div>`:''}</article>`).join('')}</div>${!own?btn('Entrar nesta guilda','guild-join',`data-id="${id}" data-inviter="${inviter||''}" data-invite-code="${esc(inviteCode)}"`,'primary wide'):own.guild.id===id?`${env.isDemo?btn('Testar entrada de piloto de exemplo','guild-test-invite',`data-id="${id}"`,'secondary wide'):''}${btn('Sair da guilda','guild-member-action',`data-guild="${id}" data-id="${currentId(s)}" data-action="leave"`,'text wide')}`:''}`,'large');}
 function testInvite(id){const s=env.getState(),g=guildById(id),available=s.adminAccounts.filter(a=>!membership(s,a.profile.id));modal(`<h2 id="modal-title">Testar um convite à guilda</h2><p>Entrada de perfil identificado como exemplo. Os bônus serão moedas fictícias.</p><form id="guild-test-invite-form" data-id="${id}"><label class="form-field"><span>Piloto de exemplo</span><select name="userId">${available.map(a=>`<option value="${a.profile.id}">${esc(a.profile.name)}</option>`).join('')}</select></label><label class="form-field"><span>Quem convidou</span><select name="inviterId">${g.members.map(m=>`<option value="${m.userId}">${esc(profileOf(s,m.userId)?.name)}</option>`).join('')}</select></label><button class="btn primary wide" type="submit" ${!available.length?'disabled':''}>Testar entrada</button></form>`);}
 function tradeForm(){const s=env.getState();modal(`<img class="social-modal-art" src="${assetUrl('trade-terminal.png')}" alt="Terminal"><h2 id="modal-title">Qual história seu robô vai seguir?</h2><form id="trade-create-form">${env.robotSelector()}<label class="form-field"><span>Tipo de oferta</span><select name="kind"><option value="sale">Vender por LifeCoins</option><option value="swap">Receber propostas de troca</option></select></label>${input('Preço em LC (somente venda)','priceLC',500,'number',`min="${socialConfig(s).tradeMinPriceLC}" max="${socialConfig(s).tradeMaxPriceLC}" step="1"`)}<p>O robô fica reservado, sem batalhar ou evoluir, até cancelar/concluir. Sua produção continua com o proprietário atual.</p><button class="btn primary wide" type="submit">Criar oferta</button></form>`);}
 function openTrade(id){const s=env.getState(),l=s.social.listings.find(l=>l.id===id);let info;if(env.isDemo){const a=accountOf(s,l.sellerId),r=a.robots.find(r=>r.uid===l.robotUid);info=C.robotInfo(a,{...r,equipment:[]});}else info=l.robotSnapshot;if(!info)throw new Error('Dados públicos da oferta ainda não foram carregados.');modal(`${sprite(info,'trade-modal-robot')}<h2 id="modal-title">${esc(info.name)} · ${l.kind==='sale'?'Aquisição no mercado':'Proposta de troca'}</h2><p>Prazo e valor de devolução seguem o robô. Equipamentos permanecem com o vendedor.</p><div class="detail-grid"><div><small>Prazo restante</small><b>${Math.ceil((info.expires-Date.now())/C.DAY)} dias</b></div><div><small>Devolução futura</small><b>${info.principalReturnLC} LC</b></div><div><small>Produção sem peças</small><b>${info.daily} RC/dia</b></div><div><small>Usos restantes</small><b>${info.remainingBattles}</b></div></div>${l.kind==='sale'?`<p>Aquisição: ${l.priceLC} LC. Taxa de ${l.feePercent}% descontada do recebimento do vendedor.</p>${btn('Confirmar aquisição','trade-buy',`data-id="${id}"`,'primary wide')}`:`<form id="trade-propose-form" data-id="${id}">${env.robotSelector()}<p>Taxa: ${l.swapFeeRC} RC por participante após aceitação. A proposta reserva seu robô e espera a outra parte.</p><button class="btn primary wide" type="submit">Enviar proposta</button></form>`}`,'large');}
 return {chat,chatPanel,getChannel,roomTitle,guilds,events:()=>`${heading('EVENTOS','Os faróis têm hora para despertar.','Acompanhe datas, mapas e recompensas de cada edição.')}${note()}${eventCards(env.getState())}`,market,createGuildForm,roster,testInvite,tradeForm,openTrade,inviteLink,setRoom:value=>{if(['global','market','guild'].includes(value))room=value;},getRoom:()=>room};
}
